import{_ as a,a as e,b as n,c as r,d as s,e as l,f as c,g as h,h as d,i as g,j as m,k as p,l as u,m as f,n as w,o as _,p as y,q as b,r as k,s as v,t as x,u as P,v as z,w as D,x as C,y as q,z as S,A,B as I,C as E,D as T,E as O,F as j,G as L,H as M,I as F,J as W,K as N,L as B,M as R,N as U,O as G,P as o,Q as H,R as X,S as Q,T as V,U as Z,V as K,W as J,X as $}from"./chunks/image7.DNVbcxI-.js";import{_ as i}from"./chunks/image6.CP232qgI.js";import{_ as Y}from"./chunks/image2.DLIlWW7l.js";import{_ as tt,o as et,c as ot,ah as it}from"./chunks/framework.DE1cwP7O.js";const at="/projects/DaDablock-AI/en/starter-kit/assets/16.Be0YhmXG.png",nt="/projects/DaDablock-AI/en/starter-kit/assets/17.B0SzEvTh.png",rt="/projects/DaDablock-AI/en/starter-kit/assets/18.gD4WXimG.png",st="/projects/DaDablock-AI/en/starter-kit/assets/image1.xOQkFzOy.png",lt="/projects/DaDablock-AI/en/starter-kit/assets/image2.DuyMPDw2.png",ct="/projects/DaDablock-AI/en/starter-kit/assets/image3.iTwzmnhz.png",ht="/projects/DaDablock-AI/en/starter-kit/assets/image4.DRkInU8K.png",dt="/projects/DaDablock-AI/en/starter-kit/assets/image1.Hb_dPJWr.png",gt="/projects/DaDablock-AI/en/starter-kit/assets/image2.DUscFuCm.png",mt="/projects/DaDablock-AI/en/starter-kit/assets/image3.BMtDhVDd.png",pt="/projects/DaDablock-AI/en/starter-kit/assets/image4.BBu3HQsu.png",ut="/projects/DaDablock-AI/en/starter-kit/assets/image5.DL3pFkf4.png",ft="/projects/DaDablock-AI/en/starter-kit/assets/image7.BJ7LQ1S2.png",wt="/projects/DaDablock-AI/en/starter-kit/assets/image1.C3rbkadd.png",_t="/projects/DaDablock-AI/en/starter-kit/assets/image3.DaearKL0.png",At=JSON.parse('{"title":"2. Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2_Quick_Start.md","filePath":"docs/2_Quick_Start.md"}'),yt={name:"docs/2_Quick_Start.md"};function bt(kt,t,vt,xt,Pt,zt){return et(),ot("div",null,[...t[0]||(t[0]=[it('<h1 id="_2-quick-start" tabindex="-1">2. Quick Start <a class="header-anchor" href="#_2-quick-start" aria-label="Permalink to &quot;2. Quick Start&quot;">​</a></h1><h2 id="_2-1-llm-interaction" tabindex="-1">2.1 LLM Interaction <a class="header-anchor" href="#_2-1-llm-interaction" aria-label="Permalink to &quot;2.1 LLM Interaction&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This section is introduced to quickly get started with the WonderLLM module. For detailed and diverse feature, refer to <a href="https://wiki.hiwonder.com/projects/DaDablock-AI/en/ultimate-kit/docs/4_Software_and_Hardware_Guide.html#_4-4-wonderllm-module" target="_blank" rel="noreferrer">4.4 WonderLLM Module</a> for learning.</strong></p></div><h3 id="_2-1-1-powering-on-the-device" tabindex="-1">2.1.1 Powering On the Device <a class="header-anchor" href="#_2-1-1-powering-on-the-device" aria-label="Permalink to &quot;2.1.1 Powering On the Device&quot;">​</a></h3><ol><li>The module supports power supply through three interfaces: <strong>① Type-C interface on the top</strong>, <strong>② Type-C interface on the bottom</strong>, and <strong>③ 4-PIN I2C communication interface</strong>. Connect an external power supply device to any interface to automatically power on the module.</li></ol><img loading="lazy" height="672" width="704" src="'+a+'" class="common_img" style="width:300px;"><ol start="2"><li>After powering on the module, the screen displays the <strong>device hotspot name</strong> and <strong>browser network configuration URL</strong> accompanied by a voice announcement. Complete the module device network connection first according to <a href="#section-2-1-2">Network Configuration</a>.</li></ol><img loading="lazy" height="2144" width="1824" src="'+e+'" class="common_img" style="width:300px;"><ol start="3"><li>After completing network configuration, the module needs to be bound to the platform agent. The screen displays the <strong>device ID</strong> and <strong>device binding platform URL</strong> accompanied by a voice announcement of the verification code. Complete the device binding according to <a href="#section-2-1-4">Device Binding</a>.</li></ol><img loading="lazy" height="1276" width="1072" src="'+n+'" class="common_img" style="width:300px;"><ol start="4"><li>After powering on, if device binding has been completed, a white circular scroll bar is displayed on the screen while the module automatically connects to the network using the Wi-Fi information saved in internal storage. If network connection fails, the screen displays the <strong>device hotspot name</strong> and <strong>browser network configuration URL</strong> accompanied by a voice announcement. Reconfigure new Wi-Fi connection details available in the current environment according to <a href="#section-2-1-2">Network Configuration</a>.</li></ol><img loading="lazy" height="723" width="650" src="'+r+'" class="common_img" style="width:300px;"><ol start="5"><li>After powering on, if device binding has been completed and the configured Wi-Fi connection information is available in the current environment, the network connects successfully after the white circular scroll bar loads for a period, jumping to the expression display interface of the module. At this point, all configurations of the module are normal, and human-robot interaction can start after waking up the module.</li></ol><img loading="lazy" height="725" width="627" src="'+s+'" class="common_img" style="width:300px;"><p><a id="section-2-1-2"></a></p><h3 id="_2-1-2-connecting-the-module-to-the-network" tabindex="-1">2.1.2 Connecting the Module to the Network <a class="header-anchor" href="#_2-1-2-connecting-the-module-to-the-network" aria-label="Permalink to &quot;2.1.2 Connecting the Module to the Network&quot;">​</a></h3><ol><li>After powering on, the module starts the network connection operation. The screen displays the <strong>device hotspot name</strong> and <strong>browser network configuration URL</strong> accompanied by a voice announcement. The LLM module opens its built-in hotspot for connection and configuration. Different devices have different hotspot names, formatted uniformly as <strong>Robot-xxxx</strong>. The hotspot <strong>Robot-B7B9</strong> is used as an example below.</li></ol><img loading="lazy" height="2144" width="1824" src="'+e+'" class="common_img" style="width:300px;"><ol start="2"><li>Search for the corresponding hotspot using a computer or mobile phone and connect, with no password required for this hotspot.</li></ol><img loading="lazy" height="186" width="359" src="'+l+'" class="common_img" style="width:400px;"><img loading="lazy" height="139" width="359" src="'+c+'" class="common_img" style="width:400px;"><ol start="3"><li>Click the <a href="http://192.168.4.1/" target="_blank" rel="noreferrer">Network Configuration</a> hyperlink to directly access the device network configuration URL, or copy the URL below, open any browser, and enter the device network configuration URL.</li></ol><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">192.168</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.4.1</span></span></code></pre></div><img loading="lazy" height="546" width="1185" src="'+h+'" class="common_img" style="width:800px;"><ol start="4"><li>Enter the desired hotspot name for automatic connection upon power-on in area ① in the figure below, and enter the connection password in area ②. Finally, click <strong>Connect</strong> in area ③. The module will attempt to search for and connect to a matching hotspot in the current environment based on the provided connection details.</li></ol><img loading="lazy" height="244" width="1165" src="'+d+'" class="common_img" style="width:800px;"><ol start="5"><li>A list of available hotspots in the current environment scanned by the module can be found on the interface. Clicking an item will automatically fill the corresponding hotspot name into area ①, which is more convenient and time-saving.</li></ol><img loading="lazy" height="224" width="375" src="'+g+'" class="common_img" style="width:500px;"><ol start="6"><li>If the following prompt appears on the interface, it indicates that the hotspot cannot be found in the current environment or the connection password is incorrect. Please re-enter the details.</li></ol><img loading="lazy" height="364" width="1163" src="'+m+'" class="common_img" style="width:800px;"><ol start="7"><li>If the following prompt appears on the interface, it indicates that the module has successfully found and connected to the corresponding hotspot. The module will automatically restart and connect to the corresponding hotspot.</li></ol><img loading="lazy" height="263" width="640" src="'+p+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p><strong>Do not enter hotspots that cannot be searched in the current environment, have excessively weak signals, or do not support network connection features.</strong></p></li><li><p><strong>If connection details of other hotspots were saved previously, newly saved connection details will coexist with them. Upon the next power-on operation, the module reads each saved connection detail in order to attempt matching and connecting to hotspots.</strong></p></li><li><p><strong>If the prompt &quot;Error: Failed to check for new version, will retry in xx seconds&quot; appears on the screen after network configuration is completed, it may be due to the current hotspot being unable to access the Internet or poor network quality. Please try switching networks.</strong></p></li></ul></div><p><a id="section-2-1-3"></a></p><h3 id="_2-1-3-xiaozhi-platform-account-registration-and-authentication" tabindex="-1">2.1.3 XiaoZhi Platform Account Registration and Authentication <a class="header-anchor" href="#_2-1-3-xiaozhi-platform-account-registration-and-authentication" aria-label="Permalink to &quot;2.1.3 XiaoZhi Platform Account Registration and Authentication&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>If GitHub authentication is not completed for the account, module usage is not affected, but available features are limited. Differences between unauthenticated and authenticated accounts are shown in the table below:</strong></p></div><table tabindex="0"><thead><tr><th style="text-align:center;"></th><th style="text-align:center;">Unauthenticated</th><th style="text-align:center;">Authenticated</th></tr></thead><tbody><tr><td style="text-align:center;">Model selection</td><td style="text-align:center;">Xiaozhi Lite</td><td style="text-align:center;">Xiaozhi Lite, Qwen 3.6, DeepSeek V4, Doubao Seed 2.0</td></tr><tr><td style="text-align:center;">Number of bound devices</td><td style="text-align:center;">10</td><td style="text-align:center;">100</td></tr><tr><td style="text-align:center;">Official service features</td><td style="text-align:center;">Weather, Music, Knowledge Base</td><td style="text-align:center;">Weather, Joke, Music, News, Knowledge Base</td></tr></tbody></table><ul><li><strong>XiaoZhi AI Platform Account Registration</strong></li></ul><ol><li>Click the <a href="https://xiaozhi.me/" target="_blank" rel="noreferrer">XiaoZhi AI Chatbot</a> hyperlink to directly access the device binding URL, or copy the URL below, open any browser, and enter the device binding URL.</li></ol><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">xiaozhi.me</span></span></code></pre></div><img loading="lazy" height="410" width="960" src="'+u+'" class="common_img" style="width:800px;"><ol start="2"><li>Click <strong>Console</strong> to enter the XiaoZhi AI Agent Management Platform.</li></ol><img loading="lazy" height="419" width="955" src="'+f+'" class="common_img" style="width:800px;"><ol start="3"><li>For initial login, register a platform account first.</li></ol><img loading="lazy" height="531" width="953" src="'+w+'" class="common_img" style="width:800px;"><ol start="4"><li>After filling in the corresponding information, click <strong>Send code</strong> to obtain the verification code required for account registration.</li></ol><img loading="lazy" height="526" width="957" src="'+_+'" class="common_img" style="width:800px;"><ol start="5"><li>Check the box to agree to the terms of service and privacy policy, and then click <strong>Login</strong>.</li></ol><img loading="lazy" height="532" width="956" src="'+y+'" class="common_img" style="width:800px;"><ol start="6"><li>Select and complete the corresponding information, then click <strong>Confirm</strong> to complete registration and login.</li></ol><img loading="lazy" height="542" width="958" src="'+b+'" class="common_img" style="width:800px;"><ul><li><strong>Logging in to GitHub Platform</strong></li></ul><ol><li>On the XiaoZhi platform, click <strong>GitHub Verification</strong> under the <img loading="lazy" height="32" width="28" src="'+k+'" style="width:70px;" class="inline-icon"> icon. After the interface jumps to the authentication page, click <strong>Link GitHub</strong>.</li></ol><img loading="lazy" height="419" width="1410" src="'+v+'" class="common_img" style="width:800px;"><img loading="lazy" height="762" width="1366" src="'+x+'" class="common_img" style="width:800px;"><ol start="2"><li>Wait for the page to jump to the GitHub account login page.</li></ol><img loading="lazy" height="697" width="522" src="'+P+'" class="common_img" style="width:500px;"><ol start="3"><li>If a GitHub account has already been registered, enter the username and password to log in directly and jump to <a href="#section-2-1-3-3">Binding XiaoZhi Platform and GitHub Platform</a>. If no GitHub account has been registered, click <strong>Create an account</strong>.</li></ol><img loading="lazy" height="697" width="522" src="'+z+'" class="common_img" style="width:500px;"><ol start="4"><li>Enter the personal email, login password, username, and location details in sequence on the pop-up interface, and click <strong>Create account</strong> to submit the registration information.</li></ol><img loading="lazy" height="788" width="686" src="'+D+'" class="common_img" style="width:500px;"><ol start="5"><li>Click <strong>Visual puzzle</strong> on the page to start image verification.</li></ol><img loading="lazy" height="445" width="598" src="'+C+'" class="common_img" style="width:500px;"><ol start="6"><li>After completing image verification, the GitHub platform will send a verification email to the registered email address entered previously. Open the email, copy the verification code, and enter it on the web page.</li></ol><img loading="lazy" height="573" width="883" src="'+q+'" class="common_img" style="width:500px;"><img loading="lazy" height="392" width="691" src="'+S+'" class="common_img" style="width:400px;"><ol start="7"><li>After completing registration, the web page jumps to the login page, and a pop-up window indicating successful registration is displayed.</li></ol><img loading="lazy" height="696" width="794" src="'+A+'" class="common_img" style="width:500px;"><p><a id="section-2-1-3-3"></a></p><ul><li><strong>Binding XiaoZhi Platform and GitHub Platform</strong></li></ul><ol><li>Click <strong>Authorize tenclass</strong> to complete the binding between the XiaoZhi platform and the GitHub platform.</li></ol><img loading="lazy" height="631" width="674" src="'+I+'" class="common_img" style="width:500px;"><ol start="2"><li>After completing the binding, authentication on the XiaoZhi platform is fully completed, automatically returning to the previous authentication page where the following prompt appears.</li></ol><img loading="lazy" height="759" width="1399" src="'+E+'" class="common_img" style="width:800px;"><p><a id="section-2-1-4"></a></p><h3 id="_2-1-4-device-binding" tabindex="-1">2.1.4 Device Binding <a class="header-anchor" href="#_2-1-4-device-binding" aria-label="Permalink to &quot;2.1.4 Device Binding&quot;">​</a></h3><ol><li>After completing registration, login, and authentication on the XiaoZhi platform, click <strong>Agents</strong> to enter the following interface.</li></ol><img loading="lazy" height="274" width="1440" src="'+at+'" class="common_img" style="width:800px;"><ol start="2"><li>Click the <strong>∨</strong> button next to the add device button, and then click <strong>Create Agent</strong>.</li></ol><img loading="lazy" height="259" width="939" src="'+T+'" class="common_img" style="width:800px;"><ol start="3"><li>Fill in the agent name, and then click <strong>Confirm</strong> to complete adding the agent.</li></ol><img loading="lazy" height="275" width="530" src="'+O+'" class="common_img" style="width:500px;"><ol start="4"><li>Click <strong>Configure</strong> to configure various functions for the agent.</li></ol><img loading="lazy" height="411" width="932" src="'+j+'" class="common_img" style="width:800px;"><ol start="5"><li>Click <strong>Role</strong> to configure the role of the agent. Select the desired dialogue language in area ①, select the desired role voice in area ②, and adjust voice settings in area ③.</li></ol><img loading="lazy" height="724" width="743" src="'+L+'" class="common_img" style="width:800px;"><ol start="6"><li>Click <strong>Model &amp; Memory</strong>, select <strong>DeepSeek V4 (Rich Personality)</strong> for the language model option, disable the memory feature, and keep all other options as default.</li></ol><img loading="lazy" height="726" width="759" src="'+nt+'" class="common_img" style="width:800px;"><img loading="lazy" height="724" width="751" src="'+M+'" class="common_img" style="width:800px;"><ol start="7"><li>Click <strong>Extensions</strong>, check all official service features, keep all other options as default, and finally click <strong>Save</strong>.</li></ol><img loading="lazy" height="727" width="757" src="'+rt+'" class="common_img" style="width:800px;"><ol start="8"><li>Click <strong>Devices</strong> to enter the device management feature.</li></ol><img loading="lazy" height="410" width="936" src="'+F+'" class="common_img" style="width:800px;"><ol start="9"><li>Click <strong>Link new device</strong>, enter the <strong>6-digit device ID</strong> in the pop-up window, and click <strong>Link</strong>.</li></ol><img loading="lazy" height="248" width="964" src="'+W+'" class="common_img" style="width:800px;"><img loading="lazy" height="238" width="969" src="'+N+'" class="common_img" style="width:800px;"><ol start="10"><li>If the binding is successful, the prompt <strong>Device Added Successfully</strong> is displayed on the page. Then select <strong>Open Source Version</strong> and click <strong>Start Using</strong>.</li></ol><img loading="lazy" height="736" width="929" src="'+B+'" class="common_img" style="width:800px;"><h3 id="_2-1-5-free-chat" tabindex="-1">2.1.5 Free Chat <a class="header-anchor" href="#_2-1-5-free-chat" aria-label="Permalink to &quot;2.1.5 Free Chat&quot;">​</a></h3><ul><li><strong>Function Overview</strong></li></ul><p>The module has built-in special functions that can be triggered by voice commands during human-robot dialogue interactions. Refer to the following phrases to send commands to the WonderLLM module to query all currently supported special functions: <strong>① What features are available?</strong> and <strong>② Introduce available functions.</strong> The special functions currently supported by the module are listed below:</p><ul><li><strong>Invocation Examples</strong></li></ul><p>Refer to the following phrases to send commands to the WonderLLM module to trigger corresponding special functions:</p><ol><li>Weather query function: <strong>Check the weather in xx region.</strong></li></ol><img loading="lazy" height="601" width="540" src="'+R+'" class="common_img" style="width:300px;"><ol start="2"><li>News broadcast function: <strong>① Broadcast today&#39;s news</strong> or <strong>② Tell me about today&#39;s trending events.</strong></li></ol><img loading="lazy" height="602" width="540" src="'+U+'" class="common_img" style="width:300px;"><ol start="3"><li>Outfit advice function: <strong>What is a suitable outfit for going out today?</strong></li></ol><img loading="lazy" height="613" width="551" src="'+G+'" class="common_img" style="width:300px;"><ol start="4"><li>Joke telling function: <strong>① Tell a joke</strong> or <strong>② Tell a joke to entertain.</strong></li></ol><img loading="lazy" height="613" width="551" src="'+o+'" class="common_img" style="width:300px;"><ol start="5"><li>Almanac query function: <strong>Check today&#39;s almanac items.</strong></li></ol><img loading="lazy" height="613" width="551" src="'+H+'" class="common_img" style="width:300px;"><ol start="6"><li><p>Music playback function: <strong>Play a random song.</strong></p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>It is recommended to lower the module volume when using the music playback function.</strong></p></div></li></ol><img loading="lazy" height="613" width="551" src="'+o+'" class="common_img" style="width:300px;"><h2 id="_2-2-hardware-preparation" tabindex="-1">2.2 Hardware Preparation <a class="header-anchor" href="#_2-2-hardware-preparation" aria-label="Permalink to &quot;2.2 Hardware Preparation&quot;">​</a></h2><h3 id="_2-2-1-powering-on" tabindex="-1">2.2.1 Powering On <a class="header-anchor" href="#_2-2-1-powering-on" aria-label="Permalink to &quot;2.2.1 Powering On&quot;">​</a></h3><ol><li><p>Insert the battery into the battery slot at the bottom of the controller.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Do not reverse the positive and negative poles.</strong></p></div></li></ol><img loading="lazy" height="1200" width="1200" src="'+st+'" class="common_img" style="width:300px;"><ol start="2"><li>Turn on the power switch. The red power indicator light on the controller glowing red indicates successful powering on.</li></ol><img loading="lazy" height="656" width="486" src="'+lt+'" class="common_img" style="width:250px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>When powering on for the first time, follow the steps in Section 2.2.2 Charging to charge through the charging port for about 5 seconds to activate the built-in battery protection chip. If the battery is not removed after activation, no further activation is required in the future.</strong></p></div><h3 id="_2-2-2-charging" tabindex="-1">2.2.2 Charging <a class="header-anchor" href="#_2-2-2-charging" aria-label="Permalink to &quot;2.2.2 Charging&quot;">​</a></h3><ol><li>Ensure the power switch of the controller is set to the <strong>OFF</strong> position. Connect one end of the USB cable to the charging interface of the controller and the other end to the charger.</li></ol><img loading="lazy" height="1146" width="860" src="'+ct+'" class="common_img" style="width:450px;"><ol start="2"><li>During charging, the LED indicator on the controller glows blue. Once fully charged, the LED turns off. Unplug the power cable promptly after charging is complete to avoid overcharging.</li></ol><img loading="lazy" height="2961" width="3214" src="'+ht+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The power switch must be turned off during charging, otherwise the battery cannot be fully charged. Unplug the charger and power supply promptly after charging is complete to avoid overcharging and damaging the battery. Someone must be present during charging.</strong></p></div><h2 id="_2-3-software-configuration" tabindex="-1">2.3 Software Configuration <a class="header-anchor" href="#_2-3-software-configuration" aria-label="Permalink to &quot;2.3 Software Configuration&quot;">​</a></h2><h3 id="_2-3-1-wondercode-software-package" tabindex="-1">2.3.1 WonderCode Software Package <a class="header-anchor" href="#_2-3-1-wondercode-software-package" aria-label="Permalink to &quot;2.3.1 WonderCode Software Package&quot;">​</a></h3><ul><li><p><a href="https://drive.google.com/file/d/1X8SvOM01UXOM2IvFwN_Ty7Ert5NPqZr8/view?usp=sharing" target="_blank" rel="noreferrer">WonderCode Windows Version</a></p></li><li><p><a href="https://hiwonder.com.cn/download/pcSoftware?get_pc=1&amp;os=mac" target="_blank" rel="noreferrer">WonderCode Mac Version</a></p></li></ul><h3 id="_2-3-2-installing-the-wondercode" tabindex="-1">2.3.2 Installing the WonderCode <a class="header-anchor" href="#_2-3-2-installing-the-wondercode" aria-label="Permalink to &quot;2.3.2 Installing the WonderCode&quot;">​</a></h3><ol><li>Open the <strong>WonderCode setup.exe</strong> software installation package.</li></ol><img loading="lazy" height="105" width="75" src="'+X+'" class="common_img" style="width:100px;"><ol start="2"><li>Select the language, and then click <strong>OK</strong>.</li></ol><img loading="lazy" height="162" width="349" src="'+Q+'" class="common_img" style="width:400px;"><ol start="3"><li>Choose the installation location, and then click <strong>Next</strong>.</li></ol><img loading="lazy" height="415" width="582" src="'+V+'" class="common_img" style="width:500px;"><ol start="4"><li>Click <strong>Next</strong>.</li></ol><img loading="lazy" height="415" width="582" src="'+Z+'" class="common_img" style="width:500px;"><ol start="5"><li>Click <strong>Install</strong>.</li></ol><img loading="lazy" height="415" width="582" src="'+K+'" class="common_img" style="width:500px;"><img loading="lazy" height="415" width="582" src="'+J+'" class="common_img" style="width:500px;"><ol start="6"><li>After successful installation, click <strong>Finish</strong>.</li></ol><img loading="lazy" height="415" width="582" src="'+$+'" class="common_img" style="width:500px;"><h2 id="_2-4-starter-project-1-onboard-rgb-light-flashing" tabindex="-1">2.4 Starter Project 1: Onboard RGB Light Flashing <a class="header-anchor" href="#_2-4-starter-project-1-onboard-rgb-light-flashing" aria-label="Permalink to &quot;2.4 Starter Project 1: Onboard RGB Light Flashing&quot;">​</a></h2><h3 id="_2-4-1-programming" tabindex="-1">2.4.1 Programming <a class="header-anchor" href="#_2-4-1-programming" aria-label="Permalink to &quot;2.4.1 Programming&quot;">​</a></h3><ol><li>Create a new file: Open the programming software and create a new project.</li></ol><img loading="lazy" height="893" width="1386" src="'+dt+'" class="common_img" style="width:800px;"><ol start="2"><li>Add extensions:</li></ol><ul><li>Click the extension button in the bottom left corner.</li></ul><img loading="lazy" height="893" width="1386" src="'+gt+'" class="common_img" style="width:800px;"><ul><li>Select <strong>Controller</strong> in the <strong>Choose an Extension</strong> interface to add <strong>K12 ESP32</strong>.</li></ul><img loading="lazy" height="893" width="1386" src="'+mt+'" class="common_img" style="width:800px;"><ul><li>After successful addition, the added extension package is visible on the WonderCode interface.</li></ul><img loading="lazy" height="893" width="1386" src="'+pt+'" class="common_img" style="width:800px;"><ol start="3"><li>Program:</li></ol><ul><li>Drag the corresponding blocks from the block palette to the scripting area to program. Once programmed successfully, the Python program converted from the blocks is visible in the code display and upload area.</li></ul><img loading="lazy" height="326" width="351" src="'+ut+'" class="common_img" style="width:500px;"><ul><li>The source files are available for download under <a href="https://drive.google.com/drive/folders/1C_cT51H9adfUnSPw9l57vPrQQ2A_vUBa?usp=sharing" target="_blank" rel="noreferrer">1. Source Code / 03 Program Files for Starter Projects</a>.</li></ul><h3 id="_2-4-2-downloading-the-program" tabindex="-1">2.4.2 Downloading the Program <a class="header-anchor" href="#_2-4-2-downloading-the-program" aria-label="Permalink to &quot;2.4.2 Downloading the Program&quot;">​</a></h3><img loading="lazy" height="360" width="640" src="'+i+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The connected port number is not unique. The port number connected in this section is COM3. Do not connect to COM1 as it is typically the interface for system communication. If multiple COM ports are displayed and cannot be determined, right-click This PC, click Properties -&gt; Device Manager in sequence, and check the port number corresponding to the controller, where the port containing the CH340 label is the correct port.</strong></p></div><img loading="lazy" height="129" width="240" src="'+ft+'" class="common_img" style="width:300px;"><h3 id="_2-4-3-program-outcome" tabindex="-1">2.4.3 Program Outcome <a class="header-anchor" href="#_2-4-3-program-outcome" aria-label="Permalink to &quot;2.4.3 Program Outcome&quot;">​</a></h3><p>After downloading the program successfully, the two onboard RGB lights of the controller switch colors every 1 second, in the sequence of red, green, and blue.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The following starter projects are designed to facilitate a quick start with the electronic modules used in this kit. For detailed descriptions of the modules, refer to <a href="https://wiki.hiwonder.com/projects/DaDablock-AI/en/ultimate-kit/docs/4_Software_and_Hardware_Guide.html#_4-3-electronic-modules-overview" target="_blank" rel="noreferrer">4.3 Electronic Modules Overview</a> for learning.</strong></p></div><h2 id="_2-5-starter-project-2-dual-servos-and-dot-matrix-graphics-display" tabindex="-1">2.5 Starter Project 2: Dual Servos and Dot Matrix Graphics Display <a class="header-anchor" href="#_2-5-starter-project-2-dual-servos-and-dot-matrix-graphics-display" aria-label="Permalink to &quot;2.5 Starter Project 2: Dual Servos and Dot Matrix Graphics Display&quot;">​</a></h2><h3 id="_2-5-1-learning-objectives" tabindex="-1">2.5.1 Learning Objectives <a class="header-anchor" href="#_2-5-1-learning-objectives" aria-label="Permalink to &quot;2.5.1 Learning Objectives&quot;">​</a></h3><ol><li><p>Understand the dot matrix module and master the basic usage of displaying preset expression patterns on the dot matrix.</p></li><li><p>Master the angle adjustment method for the ESP32 controller to control the 270° servo, and understand the logic of variable control for servo movement.</p></li><li><p>Master the speed and direction regulation methods for the ESP32 controller to control the DC motor, and understand the control logic of forward rotation, reverse rotation, and stopping.</p></li></ol><h3 id="_2-5-2-wiring-diagram" tabindex="-1">2.5.2 Wiring Diagram <a class="header-anchor" href="#_2-5-2-wiring-diagram" aria-label="Permalink to &quot;2.5.2 Wiring Diagram&quot;">​</a></h3><p>Connect the dot matrix module cable to port <strong>P5</strong> of the ESP32 controller.</p><p>Connect the 270° block servo cable to port <strong>S1</strong> of the ESP32 controller, and insert the <strong>orange</strong> wire of the servo into the <strong>white</strong> pin of S1.</p><p>Connect the 360° block servo cable to port <strong>S2</strong> of the ESP32 controller, and insert the <strong>orange</strong> wire of the servo into the <strong>white</strong> pin of S2.</p><p>As shown in the figure:</p><img loading="lazy" height="487" width="560" src="'+wt+'" class="common_img" style="width:400px;"><h3 id="_2-5-3-programming" tabindex="-1">2.5.3 Programming <a class="header-anchor" href="#_2-5-3-programming" aria-label="Permalink to &quot;2.5.3 Programming&quot;">​</a></h3><h4 id="_1-adding-extension-libraries" tabindex="-1">1. Adding Extension Libraries <a class="header-anchor" href="#_1-adding-extension-libraries" aria-label="Permalink to &quot;1. Adding Extension Libraries&quot;">​</a></h4><p>Select <strong>Output module</strong> in the <strong>Choose an Extension</strong> interface to add the <strong>Dot matrix module</strong>.</p><img loading="lazy" height="893" width="1386" src="'+Y+'" class="common_img" style="width:800px;"><h4 id="_2-program-display" tabindex="-1">2. Program Display <a class="header-anchor" href="#_2-program-display" aria-label="Permalink to &quot;2. Program Display&quot;">​</a></h4><img loading="lazy" height="763" width="667" src="'+_t+'" class="common_img" style="width:500px;"><ul><li>The source files are available for download under <a href="https://drive.google.com/drive/folders/1C_cT51H9adfUnSPw9l57vPrQQ2A_vUBa?usp=sharing" target="_blank" rel="noreferrer">1. Source Code / 03 Program Files for Starter Projects</a>.</li></ul><h3 id="_2-5-4-downloading-the-program" tabindex="-1">2.5.4 Downloading the Program <a class="header-anchor" href="#_2-5-4-downloading-the-program" aria-label="Permalink to &quot;2.5.4 Downloading the Program&quot;">​</a></h3><img loading="lazy" height="360" width="640" src="'+i+'" class="common_img" style="width:800px;"><h3 id="_2-5-5-program-outcome" tabindex="-1">2.5.5 Program Outcome <a class="header-anchor" href="#_2-5-5-program-outcome" aria-label="Permalink to &quot;2.5.5 Program Outcome&quot;">​</a></h3><p>After the program is downloaded successfully, the interface of the dot matrix screen is initialized and its brightness is set, and the 270° block servo connected to port <code>S1</code> rotates to <code>135°</code>. Then the following loop executes: the dot matrix screen draws pattern <code>S1</code> and waits for <code>2</code> seconds, the <code>S1</code> servo rotates to <code>270°</code> and <code>0°</code> in sequence, waiting for <code>2</code> seconds after each rotation. The dot matrix screen then draws pattern <code>S2</code> and waits for <code>2</code> seconds, the 360° block servo connected to port <code>S2</code> rotates at a speed of <code>50</code> while the dot matrix screen displays text <code>ON</code>. After waiting for <code>5</code> seconds, the <code>S2</code> servo stops and the dot matrix screen displays number <code>0</code>.</p>',187)])])}const It=tt(yt,[["render",bt]]);export{At as __pageData,It as default};
